<?php require_once __DIR__.'/includes/bootstrap.php';require_login();$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT);$s=$pdo->prepare('SELECT * FROM events WHERE id=?');$s->execute([$id]);$event=$s->fetch();if(!$event){flash('error','Event not found.');redirect('/dashboard.php');}if((int)$event['user_id']!==(int)$_SESSION['user_id']){http_response_code(403);exit('You can only edit events you created.');}$errors=[];$title=$event['title'];$description=$event['description'];$location=$event['location'];$event_date=date_input($event['event_date']);if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$title=trim($_POST['title']??'');$description=trim($_POST['description']??'');$location=trim($_POST['location']??'');$event_date=$_POST['event_date']??'';if(mb_strlen($title)<3||mb_strlen($title)>150)$errors[]='Title must be between 3 and 150 characters.';if(mb_strlen($description)>5000)$errors[]='Description is too long.';if(mb_strlen($location)>200)$errors[]='Location must be 200 characters or fewer.';if(!valid_date($event_date))$errors[]='Choose a valid date and time.';if(!$errors){$s=$pdo->prepare('UPDATE events SET title=?,description=?,location=?,event_date=? WHERE id=? AND user_id=?');$s->execute([$title,$description,$location,str_replace('T',' ',$event_date).':00',$id,$_SESSION['user_id']]);flash('success','Event updated successfully.');redirect('/dashboard.php');}}$page_title='Edit event';require __DIR__.'/includes/header.php'; ?>
<section class="panel form-panel wide-form"><a class="back-link" href="dashboard.php">← Dashboard</a><h1>Edit Event</h1><?php foreach($errors as $err): ?><div class="alert error"><?= e($err) ?></div><?php endforeach; ?><form method="post" data-validate><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><label>Event title<input name="title" required minlength="3" maxlength="150" value="<?= e($title) ?>"></label><label>Description<textarea name="description" rows="5" maxlength="5000"><?= e($description) ?></textarea></label><label>Location<input name="location" maxlength="200" required value="<?= e($location) ?>"></label><label>Date and time<input type="datetime-local" name="event_date" required value="<?= e($event_date) ?>"></label><button class="button primary" type="submit">Save Changes</button></form></section><?php require __DIR__.'/includes/footer.php'; ?>